import json
import sqlite3
import sys
import re
from decimal import Decimal, getcontext

def evaluate_expression(expr, params):
    # Replace all numeric literals with Decimal for precision
    def replace_literal(match):
        num_str = match.group(0)
        try:
            return str(Decimal(num_str))
        except ValueError:
            return num_str

    # Replace all variable names with their values
    def replace_var(match):
        var_name = match.group(1)
        if var_name in params:
            return str(Decimal(params[var_name]))
        return var_name

    # Tokenize the expression into numbers, variables, and operators
    tokens = re.findall(r'(\d+\.?\d*|[a-zA-Z_]\w*)|([+\-*/()])', expr)

    # Evaluate the expression using a stack-based approach
    stack = []
    for token in tokens:
        if token[0]:  # Number or variable
            if token[0].isdigit() or (token[0].startswith('-') and token[0][1:].isdigit()):
                stack.append(Decimal(token[0]))
            else:
                stack.append(Decimal(params[token[0]]))
        elif token[1]:  # Operator
            if len(stack) < 2:
                raise ValueError(f"Invalid expression: {expr}")
            b = stack.pop()
            a = stack.pop()
            if token[1] == '+':
                stack.append(a + b)
            elif token[1] == '-':
                stack.append(a - b)
            elif token[1] == '*':
                stack.append(a * b)
            elif token[1] == '/':
                if b == 0:
                    raise ValueError("Division by zero")
                stack.append(a / b)
    if len(stack) != 1:
        raise ValueError(f"Invalid expression: {expr}")
    result = stack[0]
    return float(result) if result.is_integer() else round(float(result), 6)

def replace_placeholders(sql, params):
    pattern = re.compile(r'\{\{(\w+)\}\}')
    def replacer(match):
        expr = match.group(1)
        try:
            value = evaluate_expression(expr, params)
            # Format the value to remove trailing zeros and unnecessary decimal points
            if value.is_integer():
                return str(int(value))
            else:
                return "{0:.6f}".format(value).rstrip('0').rstrip('.') if '.' in "{0:.6f}".format(value) else str(value)
        except ValueError as e:
            raise ValueError(f"Error evaluating expression {expr}: {e}")
    return pattern.sub(replacer, sql)

def process_job(job, conn):
    sql = replace_placeholders(job["sql"], job["params"])
    cursor = conn.cursor()
    cursor.execute(sql)
    rows = cursor.fetchall()
    columns = [desc[0] for desc in cursor.description]
    result = []
    for row in rows:
        row_dict = {}
        for i, col in enumerate(columns):
            value = row[i]
            if value is None:
                row_dict[col] = None
            elif isinstance(value, bytes):
                row_dict[col] = value.hex()
            else:
                row_dict[col] = value
        result.append(row_dict)
    return result

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    with open(sys.argv[1], 'r') as job_file:
        jobs_data = json.load(job_file)

    conn = sqlite3.connect(sys.argv[2])
    result = {}

    for job in jobs_data["jobs"]:
        name = job["name"]
        result[name] = process_job(job, conn)

    print(json.dumps(result))

if __name__ == "__main__":
    main()

import json
import sqlite3
import sys
import re
from decimal import Decimal, getcontext

def evaluate_expression(expr, params):
    # Set precision to avoid floating point inaccuracies
    getcontext().prec = 6
    try:
        # Replace all numeric literals with Decimal to avoid floating point issues
        def replace_literal(match):
            num_str = match.group(1)
            try:
                return str(Decimal(num_str))
            except ValueError:
                return match.group(0)

        # Replace all numeric literals in the expression
        expr = re.sub(r'\b\d+\.?\d*\b', replace_literal, expr)

        # Evaluate the expression with provided parameters
        local_vars = params.copy()
        return float(eval(expr, {}, local_vars))
    except Exception:
        raise ValueError(f"Error evaluating expression: {expr}")

def process_job(job, conn):
    # Replace placeholders in SQL
    for placeholder in re.finditer(r'\{\{\s*([^}]+)\s*\}\}', job['sql']):
        expr = placeholder.group(1)
        try:
            value = evaluate_expression(expr, job['params'])
            job['sql'] = job['sql'].replace(placeholder.group(0), str(value))
        except ValueError as e:
            raise ValueError(f"Invalid expression in job '{job['name']}': {e}")

    # Execute SQL and fetch results
    cursor = conn.cursor()
    cursor.execute(job['sql'])
    columns = [desc[0] for desc in cursor.description]
    rows = [dict(zip(columns, row)) for row in cursor.fetchall()]
    return rows

def main():
    if len(sys.argv) != 3:
        print("Usage: python jobrun.py <job_file> <database_file>", file=sys.stderr)
        sys.exit(1)

    job_file = sys.argv[1]
    db_file = sys.argv[2]

    try:
        with open(job_file, 'r') as f:
            job_data = json.load(f)
    except Exception as e:
        print(f"Error reading job file: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with sqlite3.connect(db_file) as conn:
            results = {}
            for job in job_data['jobs']:
                try:
                    rows = process_job(job, conn)
                    results[job['name']] = rows
                except Exception as e:
                    print(f"Error processing job '{job['name']}': {e}", file=sys.stderr)
                    sys.exit(1)

            print(json.dumps(results))
    except Exception as e:
        print(f"Database error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
